			writeJSONError(w, fmt.Sprintf("failed to load tenant: %v", err), http.StatusInternalServerError)
			return
		}
		if tenant == nil {
			writeJSONError(w, fmt.Sprintf("tenant %d not found", tenantID), http.StatusNotFound)
			return
		}
	} else {
