+
+	results := make([]ActivityErrorEntry, 0)
+	for rows.Next() {
+		var entry ActivityErrorEntry
+		var closeStatus int
+		var workflowTotal int
+		if err := rows.Scan(&entry.WorkflowType, &entry.Reason, &entry.Message, &closeStatus, &entry.Count, &workflowTotal); err != nil {
+			return nil, fmt.Errorf("scan stored activity error: %w", err)
+		}
+		entry.Status = workflowCloseStatusLabel(closeStatus)
+		switch {
+		case strings.TrimSpace(entry.Reason) != "":
+			entry.Error = entry.Reason
+		case strings.TrimSpace(entry.Message) != "":
+			entry.Error = entry.Message
+		default:
