+		default:
+			entry.Error = entry.Status
+		}
+		results = append(results, entry)
+	}
+	if err := rows.Err(); err != nil {
+		return nil, fmt.Errorf("iterate stored activity errors: %w", err)
+	}
+
+	return results, nil
+}
