              <button
                className="filter-chip chip-clear"
                onClick={() => onStatusFilterChange([])}
                title="Show all statuses"
              >
                Clear
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="activity-errors-note">
        <p>
          Click a workflow type to inspect the stored Cadence failure
          reasons/messages behind its count.
        </p>
