            <p>No stored workflow failures match the selected filter.</p>
          </div>
        )}
      </div>
    </div>
  );
}

function FragmentGroup({ group, isExpanded, onToggle }) {
  return (
    <>
      <tr className="activity-errors-group-row">
        <td className="workflow-type-cell">
          <button
            type="button"
            className="workflow-group-toggle"
