.activity-errors-section {
    background: var(--surface);
    border: 1px solid var(--separator);
    border-radius: var(--radius-lg);
    overflow: hidden;
}

.error-count {
    height: 22px;
    padding: 0 9px;
    border-radius: 11px;
    font-size: 11px;
    font-weight: 600;
    color: var(--warning-fg);
    background: var(--warning-bg);
    display: inline-flex;
    align-items: center;
}

.activity-errors-filters {
    padding: 10px 18px;
    border-bottom: 1px solid var(--separator);
    background: var(--surface-secondary);
}

.activity-errors-filters .filter-group {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.activity-errors-filters .filter-label {
    font-size: 11px;
    font-weight: 500;
    color: var(--fg-secondary);
    white-space: nowrap;
}

.activity-errors-filters .filter-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
    align-items: center;
}

.error-field-input {
    font-family: "SF Mono", "Menlo", "Monaco", monospace;
    font-size: 12px;
    height: var(--control-height);
    padding: 0 10px;
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    background: var(--surface);
    color: var(--fg);
    outline: none;
    transition: border-color 0.15s ease;
    min-width: 220px;
}

.error-field-input:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px var(--accent-bg);
}

.error-field-input::placeholder {
    color: var(--fg-tertiary);
}

.activity-errors-body {
    padding: 0;
}

.activity-errors-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}

