+	if err := db.QueryRowContext(ctx, `SELECT COALESCE(MAX(close_time_ns), 0) FROM workflow_failures WHERE tenant_id = $1`, tenantID).Scan(&maxNS); err != nil {
+		return 0, fmt.Errorf("latest workflow failure close time: %w", err)
