+func storedWorkflowFailureNeedsSync(ctx context.Context, tenantID int, workflowID, runID string) (bool, error) {
+	var reason string
+	var message string
+	err := db.QueryRowContext(ctx,
+		`SELECT failure_reason, failure_message FROM workflow_failures WHERE tenant_id = $1 AND workflow_id = $2 AND run_id = $3`,
+		tenantID, workflowID, runID,
+	).Scan(&reason, &message)
+	if errors.Is(err, sql.ErrNoRows) {
