const (
	workflowFailureSyncPageSize       = 200
	workflowFailureSyncMaxPages       = 10
	workflowFailureRequestSyncMaxPages = 2
	workflowFailureSyncSafetyWindow   = 5 * time.Minute
	workflowFailureInitialLookback    = 24 * time.Hour
