func syncTenantWorkflowFailures(ctx context.Context, tenant *Tenant) error {
	latestCloseNS, err := latestStoredWorkflowCloseTimeNS(ctx, tenant.ID)
	if err != nil {
		return err
	}

	fromNanos := time.Now().Add(-workflowFailureInitialLookback).UnixNano()
	if latestCloseNS > 0 {
		fromNanos = latestCloseNS - workflowFailureSyncSafetyWindow.Nanoseconds()
		if fromNanos < 0 {
			fromNanos = 0
		}
	}
	toNanos := time.Now().UnixNano()
	return syncTenantWorkflowFailuresForRange(ctx, tenant, fromNanos, toNanos, workflowFailureSyncMaxPages)
}

func syncTenantWorkflowFailuresForRange(ctx context.Context, tenant *Tenant, fromNanos, toNanos int64, maxPages int) error {
	cfg := tenantESConfig(tenant)

	for page := 0; page < maxPages; page++ {
		offset := page * workflowFailureSyncPageSize
		hits, total, err := queryRecentWorkflowsPage(cfg, []int{1, 2, 3, 5}, fromNanos, toNanos, workflowFailureSyncPageSize, offset)
		if err != nil {
			return err
		}
		if len(hits) == 0 {
			return nil
		}

		for _, hit := range hits {
			if err := syncWorkflowFailureHit(ctx, tenant, hit); err != nil {
				src := hit.Source
				log.Printf("WARN: workflow failure sync tenant=%d run %s/%s: %v", tenant.ID, src.WorkflowID, src.RunID, err)
			}
		}

		if len(hits) < workflowFailureSyncPageSize || offset+len(hits) >= total {
			return nil
		}
	}

	return nil
}

func refreshWorkflowFailures(ctx context.Context) {
	tenants, err := tenantStore.List()
	if err != nil {
		log.Printf("ERROR: workflow failure sync: list tenants: %v", err)
		return
	}
	for _, t := range tenants {
		if err := syncTenantWorkflowFailures(ctx, &t); err != nil {
			log.Printf("ERROR: workflow failure sync tenant %d: %v", t.ID, err)
		}
	}
}

func startWorkflowFailureSyncer(ctx context.Context) {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()
	log.Printf("Starting workflow failure syncer (every 30s)")

	refreshWorkflowFailures(ctx)

	for {
		select {
		case <-ctx.Done():
			log.Printf("Workflow failure syncer stopped")
			return
		case <-ticker.C:
			refreshWorkflowFailures(ctx)
		}
	}
}

