func storedWorkflowFailureNeedsSync(ctx context.Context, tenantID int, workflowID, runID string) (bool, error) {
	var exists bool
	err := db.QueryRowContext(ctx,
		`SELECT EXISTS (
			SELECT 1
			FROM workflow_failures
			WHERE tenant_id = $1 AND workflow_id = $2 AND run_id = $3
		)`,
		tenantID, workflowID, runID,
	).Scan(&exists)
	if errors.Is(err, sql.ErrNoRows) {
		return true, nil
	}
	if err != nil {
		return false, fmt.Errorf("lookup stored workflow failure %s/%s: %w", workflowID, runID, err)
	}
	return !exists, nil
}

