    const normalized = normalizeStatus(status);
    const currentNormalized = statusFilter.map(normalizeStatus);
    const newFilter = currentNormalized.includes(normalized)
      ? statusFilter.filter((s) => normalizeStatus(s) !== normalized)
      : [...statusFilter, status];
